```java
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class PaymentService {
    private static final Logger log = LoggerFactory.getLogger(PaymentService.class);

    public void processPayment(long orderId, double amount) {
        log.info("Processing payment for orderId={}, amount={}", orderId, amount);
        try {
            charge(amount);
            log.info("Payment completed for orderId={}", orderId);
        } catch (PaymentException e) {
            log.error("Payment failed for orderId={}", orderId, e); // full stack trace
        }
    }
}
// Output: 2026-06-04 10:23:45.123 INFO  [PaymentService] Processing payment for orderId=42, amount=99.99
```

Same number of lines, but now you can filter by level, correlate by timestamp, see the class, and disable it in production with one config line.

```java
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.web.servlet.HandlerInterceptor;

public class RequestLogInterceptor implements HandlerInterceptor {
    private static final Logger log = LoggerFactory.getLogger(RequestLogInterceptor.class);

    public boolean preHandle(HttpServletRequest req, HttpServletResponse res, Object handler) {
        req.setAttribute("start", System.currentTimeMillis());
        return true;
    }
    public void afterCompletion(HttpServletRequest req, HttpServletResponse res, Object h, Exception e) {
        long ms = System.currentTimeMillis() - (long) req.getAttribute("start");
        // Metadata only — never the body or auth header
        log.info("{} {} -> {} ({} ms)", req.getMethod(), req.getRequestURI(), res.getStatus(), ms);
    }
}
```

```java
// Only at DEBUG, and with sensitive fields stripped
if (log.isDebugEnabled()) {
    log.debug("Headers: {}", redact(headers));      // strip Authorization, Cookie
    log.debug("Query: {}", req.getQueryString());
}

private Map<String,String> redact(Map<String,String> h) {
    Map<String,String> safe = new HashMap<>(h);
    safe.replaceAll((k, v) -> SENSITIVE.contains(k.toLowerCase()) ? "***" : v);
    return safe; // password, authorization, cookie, card -> ***
}
```

Guarding with `isDebugEnabled()` also avoids building the detail string when DEBUG is off.

